			goto out;

		if (multiline) {
			git_str multi_value = GIT_STR_INIT;
			git_str_attach(&multi_value, value, 0);
			value = NULL;

			if (parse_multiline_variable(reader, &multi_value, quote_count % 2, line_len) < 0 ||
			    git_str_oom(&multi_value)) {
